function u(t){if(t==null||t==="")return null;if(t instanceof Date)return Number.isNaN(t.getTime())?null:t;if(typeof t=="number")return!Number.isFinite(t)||t<=0?null:new Date(t<1e12?t*1e3:t);const n=String(t).trim();if(/^\d+$/.test(n)){const r=Number(n);return new Date(r<1e12?r*1e3:r)}const e=new Date(n);return Number.isNaN(e.getTime())?null:e}function l(t){const n=u(t);return n?n.toLocaleString("zh-CN",{hour12:!1}):"—"}function h(t){const n=u(t);return n?n.toLocaleTimeString("zh-CN",{hour12:!1}):"—"}function d(t){const n=u(t);return n?`${n.getFullYear()}-${i(n.getMonth()+1)}-${i(n.getDate())}`:"—"}function c(t){return t==null||Number.isNaN(t)?"—":t.toLocaleString("zh-CN",{maximumFractionDigits:2})}function $(t){return t==null||Number.isNaN(t)?"—":t<1e3?`${Math.round(t)} ms`:`${(t/1e3).toFixed(2)} s`}function N(t,n){return!t&&!n?"—":`${c(t??0)} / ${c(n??0)}`}function i(t){return t<10?`0${t}`:String(t)}function g(t){return`${t.getFullYear()}-${i(t.getMonth()+1)}-${i(t.getDate())}`}function D(t){const n=new Date(t.getFullYear(),t.getMonth(),1),e=new Date(t.getFullYear(),t.getMonth()+1,0);return{from:g(n),to:g(e),days:e.getDate()}}function M(t){return`${t.getFullYear()} 年 ${t.getMonth()+1} 月`}const m=["日","一","二","三","四","五","六"];function b(t,n){const e=new Date(t.getFullYear(),t.getMonth(),n);return m[e.getDay()]}function w(t,n){return!t||!n||n<=0?0:Math.max(0,Math.min(100,Math.round(t/n*100)))}function F(t,n=Date.now()){const e=u(t);if(!e)return"";const r=Math.floor((n-e.getTime())/1e3);if(r<45)return"刚刚";const a=Math.floor(r/60);if(a<60)return`${a} 分钟前`;const f=Math.floor(a/60);if(f<24)return`${f} 小时前`;const o=Math.floor(f/24);if(o<30)return`${o} 天前`;const s=Math.floor(o/30);return s<12?`${s} 个月前`:`${Math.floor(o/365)} 年前`}export{l as a,c as b,d as c,i as d,D as e,h as f,g,$ as h,N as i,M as m,w as p,F as r,u as t,b as w};
